#include <bits/stdc++.h>
using namespace std;

typedef long long LL;
typedef pair<LL, LL> P;

const int MAXN = 100002;
const LL INF_NUM = 1000000007;
const long double EPSILON = 1e-15;

LL x_val, y_val, max_b;
long double min_diff = INF_NUM;
P answer_pair;

void check_and_save(LL b, LL a) {
    long double diff = fabs((long double)a / b - (long double)x_val / y_val);
    if (diff + EPSILON < min_diff) {
        min_diff = diff;
        answer_pair = {b, a};
    }
}

int main() {
    cin >> x_val >> y_val >> max_b;
    for (LL b = 1; b <= max_b; ++b) {
        LL a1 = (x_val * b) / y_val;
        LL a2 = a1 + 1;
        check_and_save(b, a1);
        check_and_save(b, a2);
    }
    cout << answer_pair.second << '/' << answer_pair.first;
    return 0;
}
